// action row-level security and integrity — generated by `pnpm gen:migration` (02-architecture §4,
// 04-testing §3); E5 AC1 / SOP-DEL-03 cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  action,
  client,
  createDatabase,
  eq,
  inActorTransaction,
  migrateUp,
  site,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const siteB = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (id: string, clientId: string, projectId: string) => ({
  id,
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo: 1,
  name: 'Site 001',
  standard: 'S' as const,
});
const actionOf = (
  clientId: string,
  siteId: string | null,
  title: string,
  more: Partial<typeof action.$inferInsert> = {},
) => ({
  id: randomUUID(),
  clientId,
  siteId,
  title,
  ownerId: staff.id,
  due: '2026-11-13',
  sourceKind: 'visit' as const,
  createdBy: staff.id,
  ...more,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(action)).map((r) => r.title).sort(),
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([siteOf(siteA, clientA, 'CLIENTA-ES-MAD-001'), siteOf(siteB, clientB, 'CLIENTB-ES-MAD-001')]);
    await tx.insert(action).values([
      actionOf(clientA, siteA, 'Send the fibre spec', { visibility: 'client' }),
      actionOf(clientA, siteA, 'Provide the floor plan', {
        ownerId: null,
        ownerName: 'Person A (client IT)',
      }),
      actionOf(clientB, siteB, 'Book the installer'),
    ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every action', async () => {
  expect(await visibleTo(staff)).toHaveLength(3);
});

it('a client sees only its own actions marked for clients', async () => {
  expect(await visibleTo(userOfA)).toEqual(['Send the fibre spec']);
  expect(await visibleTo(userOfB)).toEqual([]);
});

it('a partner sees nothing until a partner policy exists', async () => {
  expect(await visibleTo(partnerOfA)).toEqual([]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) => tx.insert(action).values(actionOf(clientA, siteA, 'X'))),
  ).rejects.toThrow();
});

it('every action has exactly one owner — a user or a named outside person (SOP-DEL-03)', async () => {
  await expect(
    asStaff((tx) => tx.insert(action).values(actionOf(clientA, siteA, 'No owner', { ownerId: null }))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) =>
      tx.insert(action).values(actionOf(clientA, siteA, 'Two owners', { ownerName: 'Person B' })),
    ),
  ).rejects.toThrow();
});

it('an action is linked to something of its own client, and has a title', async () => {
  await expect(
    asStaff((tx) => tx.insert(action).values(actionOf(clientA, null, 'Unlinked'))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(action).values(actionOf(clientA, siteB, 'Wrong client'))),
  ).rejects.toThrow();
  await expect(asStaff((tx) => tx.insert(action).values(actionOf(clientA, siteA, '  ')))).rejects.toThrow();
});

it('done carries the date it was done; the source is one of E5 AC1', async () => {
  await expect(
    asStaff((tx) => tx.update(action).set({ status: 'done' }).where(eq(action.title, 'Book the installer'))),
  ).rejects.toThrow();
  await asStaff((tx) =>
    tx
      .update(action)
      .set({ status: 'done', doneAt: new Date() })
      .where(eq(action.title, 'Book the installer')),
  );
  await expect(
    asStaff((tx) =>
      tx.insert(action).values(actionOf(clientA, siteA, 'Odd source', { sourceKind: 'rumour' as 'mail' })),
    ),
  ).rejects.toThrow();
});
